<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/academy/course?id=<?= (int)$course['id'] ?>">Volver al curso</a><p class="text-muted"><?= e($course['titulo']) ?></p><h1 class="h3 mb-4"><?= e($lesson['titulo']) ?></h1>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<article class="card card-body mb-4"><?php if ($lesson['contenido']): ?><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($lesson['contenido']) ?></div><?php endif; ?><?php if ($lesson['video_url'] && filter_var($lesson['video_url'],FILTER_VALIDATE_URL) && parse_url($lesson['video_url'],PHP_URL_SCHEME)==='https'): ?><a class="btn btn-outline-primary align-self-start mt-3" href="<?= e($lesson['video_url']) ?>" target="_blank" rel="noopener noreferrer">Abrir video en otra pestaña</a><?php endif; ?></article>
<?php if ($enrollment && $course['estado'] && $course['publicado']): ?><form method="post" action="<?= BASE_URL ?>/academy/complete?id=<?= (int)$lesson['id'] ?>" class="mb-4"><?= Csrf::field() ?><input type="hidden" name="done" value="<?= $done ? '0' : '1' ?>"><button class="btn <?= $done ? 'btn-outline-secondary' : 'btn-success' ?>"><?= $done ? 'Marcar como pendiente' : 'Marcar lección completada' ?></button></form><?php else: ?><p class="text-muted">Vista previa del contenido. Inscríbete en el curso publicado para registrar progreso.</p><?php endif; ?>
<section class="card card-body"><h2 class="h5">Otras lecciones</h2><?php foreach ($lessons as $item): ?><a class="py-2" href="<?= BASE_URL ?>/academy/lesson?id=<?= (int)$item['id'] ?>"><?= e($item['titulo']) ?><?= $item['completada'] ? ' · Completada' : '' ?></a><?php endforeach; ?></section>
